{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "FECUMI-101, a close analogue sharing the butyl-N-arylpiperazine side chain and a dione heterocycle, effectively crossed the baboon BBB in PET studies, supporting meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A pyridinone analogue with the same butyl-N-arylpiperazine motif showed a brain:plasma ratio of 3.7 in rat, directly demonstrating good brain penetration for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A related arylpiperazine heteroaromatic compound achieved a brain-to-plasma AUC ratio of 20.3 in rat, confirming that this structural family can rapidly enter the brain.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A lower-similarity amide-linked arylpiperazine analogue was an ABC-transporter efflux substrate with poor baseline brain uptake, indicating that some members of this broad family can fail; however, the query lacks the amide linker and more closely resembles permeable dione analogues.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C04"],
      "claim": "RGH-1756, a butoxy-linked arylpiperazine, showed low whole-brain uptake in monkey, providing a negative counterexample; its ether linker and larger aryl group differ from the query's butylamine linker and smaller 2-fluorophenyl group.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: the query's butyl-N-arylpiperazine dione chemotype is represented by multiple direct BBB-permeable analogues (baboon PET, rat brain:plasma 3.7, rat AUC ratio 20.3), and the xanthine core is expected to be CNS-permeable; negative efflux examples are structurally more distant.",
  "evidence_gaps": [
    "No direct experimental measurement for the exact query molecule.",
    "All Morgan similarities are moderate (<0.37); transfer relies on shared side-chain pharmacophore rather than exact scaffold match.",
    "BBB efflux liability of the query is not directly tested; some related amide/ether-linked analogues are substrates.",
    "Cross-species differences (baboon, rat, mouse, monkey) and PET-tracer conditions may not fully predict therapeutic CNS exposure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

